-- 001_init.sql — OpportunityOS full schema (PostgreSQL 15+)
-- Applied by scripts/migrate.js and tracked in schema_migrations.
-- Conventions (migrated from MySQL):
--   identity PKs      -> BIGINT GENERATED BY DEFAULT AS IDENTITY
--   TINYINT(1) booleans -> SMALLINT (0/1; repos compare Number(x))
--   ENUM(x)           -> VARCHAR(n) + named CHECK constraint (renamed per migration)
--   JSON              -> JSONB
--   inline INDEX/KEY  -> CREATE INDEX after the table
--   UNIQUE KEY uq_... -> CONSTRAINT uq_... UNIQUE

CREATE TABLE IF NOT EXISTS schema_migrations (
  migration   VARCHAR(100) PRIMARY KEY,
  applied_at  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

DROP TABLE IF EXISTS audit_logs, ai_jobs, search_jobs, search_queries,
  pipeline_events, outreach_messages, opportunity_solutions, financial_scenarios,
  opportunity_assumptions, opportunity_evidence, opportunities,
  solution_industries, solution_problems, solutions, business_evidence,
  business_contacts, business_sources, businesses, sessions, users CASCADE;

-- ---------------------------------------------------------------- users
CREATE TABLE users (
  id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name          VARCHAR(120) NOT NULL,
  email         VARCHAR(255) NOT NULL UNIQUE,
  password_hash VARCHAR(255) NOT NULL,           -- scrypt hash; auth_identifier for future SSO
  role          VARCHAR(10) NOT NULL DEFAULT 'analyst'
                CONSTRAINT chk_users_role CHECK (role IN ('admin','analyst')),
  status        VARCHAR(10) NOT NULL DEFAULT 'active'
                CONSTRAINT chk_users_status CHECK (status IN ('active','suspended')),
  created_at    TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at    TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- Sessions (auth infrastructure; not a domain entity)
CREATE TABLE sessions (
  token      CHAR(64) PRIMARY KEY,
  user_id    BIGINT NOT NULL,
  expires_at TIMESTAMP NOT NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_sessions_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

-- ---------------------------------------------------------------- businesses
-- normalized_name / website_normalized / phone_normalized exist to support
-- deduplication across name, website, phone and social/external identifiers.
CREATE TABLE businesses (
  id                       BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name                     VARCHAR(200) NOT NULL,
  normalized_name          VARCHAR(200) NOT NULL,        -- aggressively normalized (lib/normalize.js)
  industry                 VARCHAR(120) NULL,
  description              TEXT NULL,
  location                 VARCHAR(160) NULL,
  country                  VARCHAR(120) NULL,
  website                  VARCHAR(500) NULL,
  website_normalized       VARCHAR(255) NULL,
  phone_normalized         VARCHAR(24)  NULL,            -- primary public phone, E.164-style digits
  estimated_size           VARCHAR(60)  NULL,            -- e.g. '10-50 employees'
  employee_signal          VARCHAR(255) NULL,
  branch_count             SMALLINT NOT NULL DEFAULT 1,
  business_maturity_score  SMALLINT NULL CHECK (business_maturity_score BETWEEN 0 AND 100),
  business_maturity_notes  TEXT NULL,
  primary_social_platform  VARCHAR(80)  NULL,
  data_origin              VARCHAR(16) NOT NULL DEFAULT 'manual'
                           CONSTRAINT chk_businesses_data_origin CHECK (data_origin IN ('manual','demo','provider')),
  created_by               BIGINT NULL,
  created_at               TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at               TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uq_businesses_normalized_name UNIQUE (normalized_name),
  CONSTRAINT fk_businesses_user FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE SET NULL
);

CREATE INDEX idx_businesses_website_norm ON businesses (website_normalized);
CREATE INDEX idx_businesses_phone ON businesses (phone_normalized);

CREATE TABLE business_sources (
  id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  business_id         BIGINT NOT NULL,
  source_type         VARCHAR(24)
                      CONSTRAINT chk_bsources_source_type CHECK (source_type IN
                        ('manual_entry','demo_data','web_directory','social_media','referral','provider_api','other'))
                      NOT NULL DEFAULT 'other',
  source_name         VARCHAR(200) NOT NULL,
  source_url          VARCHAR(500) NULL,
  external_identifier VARCHAR(255) NULL,             -- platform-specific id or social URL handle
  source_status       VARCHAR(16) NOT NULL DEFAULT 'active'
                      CONSTRAINT chk_bsources_source_status CHECK (source_status IN ('active','stale','unreachable')),
  discovered_at       TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at          TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uq_bsources_external UNIQUE (business_id, source_name, external_identifier),
  CONSTRAINT fk_bsources_business FOREIGN KEY (business_id) REFERENCES businesses(id) ON DELETE CASCADE
);

CREATE INDEX idx_bsources_business ON business_sources (business_id);

-- contact_value_normalized: phones stored as digits with leading '+' only.
-- WhatsApp is NEVER inferred from a phone number — it is its own contact_type
-- and must arrive with verification_status = 'source_published'/'user_confirmed'.
CREATE TABLE business_contacts (
  id                    BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  business_id           BIGINT NOT NULL,
  contact_type          VARCHAR(16) NOT NULL
                        CONSTRAINT chk_contacts_contact_type CHECK (contact_type IN
                          ('email','phone','whatsapp','social','website_form','other')),
  contact_value         VARCHAR(320) NOT NULL,
  contact_value_normalized VARCHAR(320) NULL,
  is_public             SMALLINT NOT NULL DEFAULT 1,
  verification_status   VARCHAR(24) NOT NULL DEFAULT 'unverified'
                        CONSTRAINT chk_contacts_verification_status CHECK (verification_status IN
                          ('unverified','source_published','user_confirmed','invalid')),
  confidence_score      DECIMAL(3,2) NOT NULL DEFAULT 0.50,
  source_id             BIGINT NULL,
  last_verified_at      TIMESTAMP NULL,
  created_at            TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at            TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uq_contacts_value UNIQUE (business_id, contact_type, contact_value_normalized),
  CONSTRAINT fk_contacts_business FOREIGN KEY (business_id) REFERENCES businesses(id) ON DELETE CASCADE,
  CONSTRAINT fk_contacts_source FOREIGN KEY (source_id) REFERENCES business_sources(id) ON DELETE SET NULL
);

CREATE INDEX idx_contacts_business ON business_contacts (business_id);

-- signal_key (beyond spec) drives the deterministic problem-detection engine.
CREATE TABLE business_evidence (
  id                     BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  business_id            BIGINT NOT NULL,
  source_id              BIGINT NULL,
  evidence_type          VARCHAR(24)
                         CONSTRAINT chk_evidence_evidence_type CHECK (evidence_type IN
                           ('observation','public_stat','customer_review','listing_detail',
                            'news','interview_note','ai_interpretation','other'))
                         NOT NULL DEFAULT 'observation',
  claim_type             VARCHAR(12) NOT NULL DEFAULT 'FACT'
                         CONSTRAINT chk_evidence_claim_type CHECK (claim_type IN ('FACT','INFERENCE','HYPOTHESIS')),
  signal_key             VARCHAR(80) NULL,
  evidence_text          TEXT NOT NULL,
  source_excerpt_summary TEXT NULL,
  confidence_score       DECIMAL(3,2) NOT NULL DEFAULT 0.50,
  captured_by            BIGINT NULL,
  captured_at            TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_at             TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_evidence_business FOREIGN KEY (business_id) REFERENCES businesses(id) ON DELETE CASCADE,
  CONSTRAINT fk_evidence_source FOREIGN KEY (source_id) REFERENCES business_sources(id) ON DELETE SET NULL,
  CONSTRAINT fk_evidence_user FOREIGN KEY (captured_by) REFERENCES users(id) ON DELETE SET NULL
);

CREATE INDEX idx_evidence_signal ON business_evidence (business_id, signal_key);

-- ---------------------------------------------------------------- solutions
CREATE TABLE solutions (
  id                     BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name                   VARCHAR(160) NOT NULL,
  slug                   VARCHAR(160) NOT NULL,
  description            TEXT NOT NULL,
  active                 SMALLINT NOT NULL DEFAULT 1,
  minimum_project_value  DECIMAL(12,2) NULL,
  maximum_project_value  DECIMAL(12,2) NULL,
  currency               CHAR(3) NOT NULL DEFAULT 'USD',
  created_at             TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at             TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uq_solutions_slug UNIQUE (slug)
);

CREATE TABLE solution_problems (
  id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  solution_id  BIGINT NOT NULL,
  problem_type VARCHAR(32) NOT NULL
               CONSTRAINT chk_sp_problem_type CHECK (problem_type IN (
                 'lost_sales','poor_conversion','manual_ordering','manual_booking',
                 'inventory_problems','multi_branch_management','customer_retention',
                 'delivery_management','quotation_management','wholesale_ordering',
                 'staff_management','payment_reconciliation','reporting',
                 'operational_inefficiency','customer_communication','scheduling',
                 'production_tracking','order_tracking','customer_service','repeat_sales',
                 'administrative_inefficiency')),
  created_at   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uq_solution_problem UNIQUE (solution_id, problem_type),
  CONSTRAINT fk_sp_solution FOREIGN KEY (solution_id) REFERENCES solutions(id) ON DELETE CASCADE
);

CREATE INDEX idx_sp_problem ON solution_problems (problem_type);

CREATE TABLE solution_industries (
  id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  solution_id BIGINT NOT NULL,
  industry    VARCHAR(120) NOT NULL,
  created_at  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uq_solution_industry UNIQUE (solution_id, industry),
  CONSTRAINT fk_si_solution FOREIGN KEY (solution_id) REFERENCES solutions(id) ON DELETE CASCADE
);

-- ---------------------------------------------------------------- opportunities
-- problem_type is included beyond the listed fields so opportunities can be
-- deduplicated per business+problem and matched against SOLUTION_PROBLEMS.
CREATE TABLE opportunities (
  id                          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  business_id                 BIGINT NOT NULL,
  title                       VARCHAR(220) NOT NULL,
  problem_type                VARCHAR(32) NOT NULL
                              CONSTRAINT chk_opps_problem_type CHECK (problem_type IN (
                                'lost_sales','poor_conversion','manual_ordering','manual_booking',
                                'inventory_problems','multi_branch_management','customer_retention',
                                'delivery_management','quotation_management','wholesale_ordering',
                                'staff_management','payment_reconciliation','reporting',
                                'operational_inefficiency','customer_communication','scheduling',
                                'production_tracking','order_tracking','customer_service','repeat_sales',
                                'administrative_inefficiency')),
  problem                     TEXT NOT NULL,
  opportunity                 TEXT NOT NULL,
  why_it_matters              TEXT NOT NULL,
  money_mechanism             VARCHAR(300) NULL,
  status                      VARCHAR(20) NOT NULL DEFAULT 'new'
                              CONSTRAINT chk_opps_status CHECK (status IN (
                                'new','analyzing','qualified','outreach_sent','in_conversation',
                                'proposal_sent','won','lost','archived')),
  confidence_score            DECIMAL(3,2) NULL,
  opportunity_score           SMALLINT NULL CHECK (opportunity_score BETWEEN 0 AND 100),
  problem_severity_score      SMALLINT NULL,
  money_potential_score       SMALLINT NULL,
  business_maturity_score     SMALLINT NULL,
  ability_to_pay_score        SMALLINT NULL,
  solution_fit_score          SMALLINT NULL,
  contactability_score        SMALLINT NULL,
  operational_complexity_score SMALLINT NULL,
  next_action                 VARCHAR(300) NULL,
  analysis_provider           VARCHAR(8) NOT NULL DEFAULT 'none'
                              CONSTRAINT chk_opps_analysis_provider CHECK (analysis_provider IN ('none','rules','llm')),
  created_by                  BIGINT NULL,
  created_at                  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at                  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uq_opps_business_problem UNIQUE (business_id, problem_type),
  CONSTRAINT fk_opps_business FOREIGN KEY (business_id) REFERENCES businesses(id) ON DELETE CASCADE,
  CONSTRAINT fk_opps_user FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE SET NULL
);

CREATE INDEX idx_opps_status ON opportunities (status);
CREATE INDEX idx_opps_score ON opportunities (opportunity_score);

CREATE TABLE opportunity_evidence (
  id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  opportunity_id  BIGINT NOT NULL,
  evidence_id     BIGINT NOT NULL,
  relevance_score DECIMAL(3,2) NOT NULL DEFAULT 0.50,
  created_at      TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uq_opp_evidence UNIQUE (opportunity_id, evidence_id),
  CONSTRAINT fk_oppev_opp FOREIGN KEY (opportunity_id) REFERENCES opportunities(id) ON DELETE CASCADE,
  CONSTRAINT fk_oppev_ev FOREIGN KEY (evidence_id) REFERENCES business_evidence(id) ON DELETE CASCADE
);

CREATE TABLE opportunity_assumptions (
  id               BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  opportunity_id   BIGINT NOT NULL,
  assumption_name  VARCHAR(80) NOT NULL,     -- average_order_value, hours_saved, ...
  assumption_value DECIMAL(14,4) NOT NULL DEFAULT 0,
  unit             VARCHAR(30) NULL,         -- currency|hours|orders|customers|ratio
  source           VARCHAR(200) NOT NULL DEFAULT 'Analyst estimate',
  confidence       DECIMAL(3,2) NOT NULL DEFAULT 0.40,
  created_at       TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uq_assumption UNIQUE (opportunity_id, assumption_name),
  CONSTRAINT fk_assumptions_opp FOREIGN KEY (opportunity_id) REFERENCES opportunities(id) ON DELETE CASCADE
);

-- impact_low/high are ILLUSTRATIVE bounds around the formula result.
-- is_illustrative must stay 1 unless a human has verified real numbers.
CREATE TABLE financial_scenarios (
  id                 BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  opportunity_id     BIGINT NOT NULL,
  scenario_type      VARCHAR(60) NOT NULL,   -- time_saved | recovered_orders | ...
  currency           CHAR(3) NOT NULL DEFAULT 'USD',
  formula_description VARCHAR(300) NOT NULL,
  impact_low         DECIMAL(14,2) NULL,
  impact_high        DECIMAL(14,2) NULL,
  period             VARCHAR(8) NOT NULL DEFAULT 'annual'
                     CONSTRAINT chk_scenarios_period CHECK (period IN ('monthly','annual')),
  assumptions_json   JSONB NULL,
  is_illustrative    SMALLINT NOT NULL DEFAULT 1,
  created_at         TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_scenarios_opp FOREIGN KEY (opportunity_id) REFERENCES opportunities(id) ON DELETE CASCADE
);

CREATE INDEX idx_scenarios_opp ON financial_scenarios (opportunity_id);

CREATE TABLE opportunity_solutions (
  id                 BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  opportunity_id     BIGINT NOT NULL,
  solution_id        BIGINT NOT NULL,
  fit_score          SMALLINT NOT NULL DEFAULT 0,
  reason             TEXT NULL,
  recommended        SMALLINT NOT NULL DEFAULT 0,
  project_value_low  DECIMAL(12,2) NULL,
  project_value_high DECIMAL(12,2) NULL,
  created_at         TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uq_oppsol UNIQUE (opportunity_id, solution_id),
  CONSTRAINT fk_opsol_opp FOREIGN KEY (opportunity_id) REFERENCES opportunities(id) ON DELETE CASCADE,
  CONSTRAINT fk_opsol_sol FOREIGN KEY (solution_id) REFERENCES solutions(id)
);

-- ---------------------------------------------------------------- outreach & pipeline
CREATE TABLE outreach_messages (
  id                BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  opportunity_id    BIGINT NOT NULL,
  message_type      VARCHAR(10) NOT NULL DEFAULT 'email'
                    CONSTRAINT chk_outreach_message_type CHECK (message_type IN ('email','whatsapp','sms','linkedin')),
  message_text      TEXT NOT NULL,
  ai_model          VARCHAR(120) NULL,        -- NULL => template-generated
  generation_status VARCHAR(10) NOT NULL DEFAULT 'pending'
                    CONSTRAINT chk_outreach_generation_status CHECK (generation_status IN ('pending','generated','failed')),
  approved          SMALLINT NOT NULL DEFAULT 0,
  sent_status       VARCHAR(10) NOT NULL DEFAULT 'not_sent'
                    CONSTRAINT chk_outreach_sent_status CHECK (sent_status IN ('not_sent','sent','failed','bounced','replied')),
  created_at        TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at        TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_outreach_opp FOREIGN KEY (opportunity_id) REFERENCES opportunities(id) ON DELETE CASCADE
);

CREATE INDEX idx_outreach_opp ON outreach_messages (opportunity_id);

CREATE TABLE pipeline_events (
  id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  opportunity_id BIGINT NOT NULL,
  from_status    VARCHAR(40) NULL,
  to_status      VARCHAR(40) NOT NULL,
  notes          VARCHAR(400) NULL,
  actor_user_id  BIGINT NULL,
  created_at     TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_events_opp FOREIGN KEY (opportunity_id) REFERENCES opportunities(id) ON DELETE CASCADE,
  CONSTRAINT fk_events_user FOREIGN KEY (actor_user_id) REFERENCES users(id) ON DELETE SET NULL
);

CREATE INDEX idx_events_opp ON pipeline_events (opportunity_id, created_at);

-- ---------------------------------------------------------------- discovery jobs
CREATE TABLE search_queries (
  id                 BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  query_name         VARCHAR(200) NOT NULL,
  query_text         VARCHAR(300) NOT NULL DEFAULT '',
  industry           VARCHAR(120) NULL,
  location           VARCHAR(160) NULL,
  platform           VARCHAR(80)  NULL,
  minimum_followers  INTEGER NULL,
  business_maturity  VARCHAR(8) NOT NULL DEFAULT 'any'
                     CONSTRAINT chk_searchqueries_maturity CHECK (business_maturity IN ('any','small','established','mature')),
  problem_categories JSONB NULL,
  status             VARCHAR(8) NOT NULL DEFAULT 'active'
                     CONSTRAINT chk_searchqueries_status CHECK (status IN ('draft','active','archived')),
  created_by         BIGINT NULL,
  created_at         TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_searchqueries_user FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE SET NULL
);

CREATE TABLE search_jobs (
  id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  search_query_id BIGINT NOT NULL,
  provider        VARCHAR(80) NOT NULL,
  status          VARCHAR(10) NOT NULL DEFAULT 'pending'
                  CONSTRAINT chk_searchjobs_status CHECK (status IN ('pending','running','completed','failed')),
  progress        SMALLINT NOT NULL DEFAULT 0,
  attempts        SMALLINT NOT NULL DEFAULT 0,
  error_message   VARCHAR(600) NULL,
  started_at      TIMESTAMP NULL,
  completed_at    TIMESTAMP NULL,
  created_at      TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_searchjobs_query FOREIGN KEY (search_query_id) REFERENCES search_queries(id) ON DELETE CASCADE
);

CREATE INDEX idx_searchjobs_status ON search_jobs (status);

CREATE TABLE ai_jobs (
  id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  job_type       VARCHAR(32) NOT NULL
                 CONSTRAINT chk_aijobs_job_type CHECK (job_type IN
                   ('research_interpretation','opportunity_analysis','outreach_draft','demo_specification')),
  business_id    BIGINT NULL,
  opportunity_id BIGINT NULL,
  user_id        BIGINT NULL,
  provider       VARCHAR(80) NULL,
  model          VARCHAR(120) NULL,
  status         VARCHAR(24) NOT NULL DEFAULT 'pending'
                 CONSTRAINT chk_aijobs_status CHECK (status IN
                   ('pending','running','completed','failed','skipped_no_provider')),
  attempts       SMALLINT NOT NULL DEFAULT 0,
  input_hash     CHAR(64) NULL,
  output_json    JSONB NULL,
  error_message  VARCHAR(600) NULL,
  started_at     TIMESTAMP NULL,
  completed_at   TIMESTAMP NULL,
  created_at     TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_aijobs_business FOREIGN KEY (business_id) REFERENCES businesses(id) ON DELETE CASCADE,
  CONSTRAINT fk_aijobs_opportunity FOREIGN KEY (opportunity_id) REFERENCES opportunities(id) ON DELETE CASCADE,
  CONSTRAINT fk_aijobs_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL
);

CREATE INDEX idx_aijobs_entity ON ai_jobs (business_id, opportunity_id);
CREATE INDEX idx_aijobs_status ON ai_jobs (status);

CREATE TABLE audit_logs (
  id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id       BIGINT NULL,
  action        VARCHAR(120) NOT NULL,
  entity_type   VARCHAR(60) NULL,
  entity_id     BIGINT NULL,
  metadata_json JSONB NULL,
  created_at    TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_audit_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL
);

CREATE INDEX idx_audit_entity ON audit_logs (entity_type, entity_id);